export type ActivityKind =
  | 'FERTILIZE'
  | 'HARVEST'
  | 'NOTE'
  | 'OBSERVE'
  | 'PRUNE'
  | 'REPOT'
  | 'WATER';

export type AnalysisFailureCode =
  | 'BUDGET_EXCEEDED'
  | 'INTERNAL'
  /** Provider answered but output failed length/schema/enum/evidence validation. */
  | 'INVALID_OUTPUT'
  /** No provider configured or owner opt-in missing; retriable once capability exists. */
  | 'PROVIDER_UNAVAILABLE'
  /** Provider 429/5xx; retried up to 3 attempts with bounded exponential jitter. */
  | 'PROVIDER_UNAVAILABLE_RETRYABLE'
  /** Schema-repair attempt also failed (one bounded repair only). */
  | 'REPAIR_FAILED'
  /** Superseded by a newer run or invalidated by target change; result discarded. */
  | 'SUPERSEDED'
  | 'TIMEOUT';

export type AnalysisKind =
  /** Identification candidates from a photo; owner confirms names (T30). */
  | 'IDENTIFICATION'
  /** Receipt extraction to an editable draft; never a confirmed purchase (T30). */
  | 'RECEIPT_EXTRACTION'
  /** Cross-record cost/care/history synthesis (T33). */
  | 'SYNTHESIS'
  /** Text analysis over bounded plant history + approved guidance (T29). */
  | 'TEXT'
  /** Vision observation over an explicit photo pair (T31). */
  | 'VISION';

export type AnalysisRunState =
  | 'CANCELLED'
  | 'FAILED'
  | 'QUEUED'
  | 'RUNNING'
  /** Terminal: target changed/deleted, run cancelled-then-late-arrived, or snapshot superseded. Readable, never actionable. */
  | 'STALE'
  | 'SUCCEEDED';

export type AnchorPolicy =
  /** Interval anchored to the last qualifying completion local date. */
  | 'LAST_QUALIFYING_COMPLETION'
  /** Interval anchored to the plan start date. */
  | 'PLAN_START';

export type AnnualWindowInput = {
  day: number;
  /** Cadence in years; default 1. Windows spanning New Year use explicit dates/region. */
  everyYears?: number | null | undefined;
  /** month 1..12, day 1..31 (validated against the month). Feb 29 maps to Feb 28 in non-leap years, recorded in reason. */
  month: number;
  /** Window length in days from the anchor date; default 1. */
  windowDays?: number | null | undefined;
};

