/** The general activity update/void commands reject activities linked to a completion with LINKED_COMPLETION_USE_CORRECTION; this is the only path to edit or undo a completion. Exactly one of undo or field edits. */
export type CorrectOccurrenceCompletionInput = {
  expectedRevision: number;
  note?: string | null | undefined;
  /** Recalculates completion-relative cadence when the local date changes; scheduled-calendar cadence stays fixed. */
  occurredAt?: string | null | undefined;
  occurrenceId: string | number;
  product?: string | null | undefined;
  quantity?: string | null | undefined;
  /** IANA zone in which occurredAt was entered; default the activity's zone. */
  timezone?: string | null | undefined;
  /** Undo voids the linked activity; per 03 the occurrence reopens only when no later resolved decision exists, otherwise COMPLETION_RETRACTED. */
  undo?: boolean | null | undefined;
  unit?: Unit | null | undefined;
};

